  1	package com.pousadamareaalta.service;
  2	
  3	import com.pousadamareaalta.model.*;
  4	import java.math.BigDecimal;
  5	import java.time.LocalDate;
  6	import java.time.YearMonth;
  7	import java.util.*;
  8	import java.util.stream.Collectors;
  9	
 10	public class ReportService {
 11	    private final RoomService roomService;
 12	    private final ReservationService reservationService;
 13	    private static final BigDecimal TOURISM_TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
 14	
 15	    public ReportService(RoomService roomService, ReservationService reservationService) {
 16	        this.roomService = roomService;
 17	        this.reservationService = reservationService;
 18	    }
 19	
 20	    public String generateOccupancyReport(LocalDate date) {
 21	        List<Reservation> occupiedReservations = getOccupiedReservations(date);
 22	
 23	        StringBuilder csv = new StringBuilder();
 24	        csv.append("Pousada Maré Alta,occupancy,").append(formatDate(date)).append("\n");
 25	        csv.append("room,type,reservation,check_in,check_out\n");
 26	
 27	        for (Reservation res : occupiedReservations) {
 28	            Room room = roomService.getRoom(res.getRoomNumber());
 29	            csv.append(res.getRoomNumber()).append(",");
 30	            csv.append(room.getType()).append(",");
 31	            csv.append(res.getId()).append(",");
 32	            csv.append(formatDate(res.getCheckIn())).append(",");
 33	            csv.append(formatDate(res.getCheckOut())).append("\n");
 34	        }
 35	
 36	        csv.append("total,").append(occupiedReservations.size()).append("/5\n");
 37	        return csv.toString();
 38	    }
 39	
 40	    public String generateRevenueReport(YearMonth month) {
 41	        List<Reservation> monthReservations = getMonthReservations(month);
 42	
 43	        StringBuilder csv = new StringBuilder();
 44	        csv.append("Pousada Maré Alta,revenue,").append(formatMonth(month)).append("\n");
 45	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 46	
 47	        BigDecimal total = BigDecimal.ZERO;
 48	        for (Reservation res : monthReservations) {
 49	            BigDecimal amount = res.getAmountPaid().subtract(res.getRefund() != null ? res.getRefund() : BigDecimal.ZERO);
 50	            csv.append(res.getId()).append(",");
 51	            csv.append(res.getRoomNumber()).append(",");
 52	            csv.append(formatDate(res.getCheckIn())).append(",");
 53	            csv.append(formatDate(res.getCheckOut())).append(",");
 54	            csv.append(res.getStatus()).append(",");
 55	            csv.append(formatMoney(amount)).append("\n");
 56	            total = total.add(amount);
 57	        }
 58	
 59	        csv.append("total,,,,").append(formatMoney(total)).append("\n");
 60	        return csv.toString();
 61	    }
 62	
 63	    public String generateTourismTaxReport(YearMonth month) {
 64	        List<Reservation> monthReservations = getPaidReservationsInMonth(month);
 65	
 66	        StringBuilder csv = new StringBuilder();
 67	        csv.append("Pousada Maré Alta,tourism-tax,").append(formatMonth(month)).append("\n");
 68	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
 69	
 70	        BigDecimal total = BigDecimal.ZERO;
 71	        for (Reservation res : monthReservations) {
 72	            BigDecimal tax = TOURISM_TAX_PER_GUEST_PER_NIGHT
 73	                .multiply(BigDecimal.valueOf(res.getGuests()))
 74	                .multiply(BigDecimal.valueOf(res.getNights()));
 75	
 76	            csv.append(res.getId()).append(",");
 77	            csv.append(res.getRoomNumber()).append(",");
 78	            csv.append(formatDate(res.getCheckIn())).append(",");
 79	            csv.append(formatDate(res.getCheckOut())).append(",");
 80	            csv.append(res.getGuests()).append(",");
 81	            csv.append(res.getNights()).append(",");
 82	            csv.append(formatMoney(tax)).append("\n");
 83	            total = total.add(tax);
 84	        }
 85	
 86	        csv.append("total,,,,,").append(formatMoney(total)).append("\n");
 87	        return csv.toString();
 88	    }
 89	
 90	    public String generateRatePlansReport(YearMonth month) {
 91	        List<Reservation> monthReservations = getMonthReservations(month);
 92	
 93	        Map<RatePlan, Integer> counts = new LinkedHashMap<>();
 94	        Map<RatePlan, BigDecimal> amounts = new LinkedHashMap<>();
 95	        counts.put(RatePlan.STANDARD, 0);
 96	        counts.put(RatePlan.NON_REFUNDABLE, 0);
 97	        amounts.put(RatePlan.STANDARD, BigDecimal.ZERO);
 98	        amounts.put(RatePlan.NON_REFUNDABLE, BigDecimal.ZERO);
 99	
100	        for (Reservation res : monthReservations) {
101	            RatePlan plan = res.getRatePlan();
102	            counts.put(plan, counts.get(plan) + 1);
103	            BigDecimal amount = res.getAmountPaid().subtract(res.getRefund() != null ? res.getRefund() : BigDecimal.ZERO);
104	            amounts.put(plan, amounts.get(plan).add(amount));
105	        }
106	
107	        StringBuilder csv = new StringBuilder();
108	        csv.append("Pousada Maré Alta,rate-plans,").append(formatMonth(month)).append("\n");
109	        csv.append("rate_plan,reservations,amount\n");
110	
111	        BigDecimal totalAmount = BigDecimal.ZERO;
112	        int totalReservations = 0;
113	
114	        for (RatePlan plan : counts.keySet()) {
115	            csv.append(plan).append(",");
116	            csv.append(counts.get(plan)).append(",");
117	            csv.append(formatMoney(amounts.get(plan))).append("\n");
118	            totalReservations += counts.get(plan);
119	            totalAmount = totalAmount.add(amounts.get(plan));
120	        }
121	
122	        csv.append("total,").append(totalReservations).append(",").append(formatMoney(totalAmount)).append("\n");
123	        return csv.toString();
124	    }
125	
126	    private List<Reservation> getOccupiedReservations(LocalDate date) {
127	        return reservationService.getAllReservations().stream()
128	            .filter(res -> res.getStatus() != ReservationStatus.CANCELLED)
129	            .filter(res -> {
130	                LocalDate nextDay = date.plusDays(1);
131	                return !res.getCheckIn().isAfter(date) && res.getCheckOut().isAfter(date);
132	            })
133	            .sorted(Comparator.comparingInt(Reservation::getRoomNumber).thenComparingLong(Reservation::getId))
134	            .collect(Collectors.toList());
135	    }
136	
137	    private List<Reservation> getMonthReservations(YearMonth month) {
138	        return reservationService.getAllReservations().stream()
139	            .filter(res -> YearMonth.from(res.getCheckIn()).equals(month))
140	            .sorted(Comparator.comparing(Reservation::getCheckIn).thenComparingLong(Reservation::getId))
141	            .collect(Collectors.toList());
142	    }
143	
144	    private List<Reservation> getPaidReservationsInMonth(YearMonth month) {
145	        return reservationService.getAllReservations().stream()
146	            .filter(res -> YearMonth.from(res.getCheckIn()).equals(month))
147	            .filter(res -> res.getStatus() != ReservationStatus.PENDING && res.getStatus() != ReservationStatus.CANCELLED)
148	            .sorted(Comparator.comparing(Reservation::getCheckIn).thenComparingLong(Reservation::getId))
149	            .collect(Collectors.toList());
150	    }
151	
152	    private String formatDate(LocalDate date) {
153	        return date.toString();
154	    }
155	
156	    private String formatMonth(YearMonth month) {
157	        return month.toString();
158	    }
159	
160	    private String formatMoney(BigDecimal amount) {
161	        return String.format("%.2f", amount);
162	    }
163	}

