     1	package com.pousadamareaalta.controller;
     2	
     3	import com.pousadamareaalta.dto.*;
     4	import com.pousadamareaalta.exception.ApiException;
     5	import com.pousadamareaalta.model.*;
     6	import com.pousadamareaalta.service.*;
     7	import io.javalin.Javalin;
     8	import java.math.BigDecimal;
     9	import java.time.LocalDate;
    10	import java.time.YearMonth;
    11	import java.time.format.DateTimeParseException;
    12	
    13	public class ReservationController {
    14	    private final RoomService roomService;
    15	    private final ReservationService reservationService;
    16	    private final MessageService messageService;
    17	    private final ReportService reportService;
    18	
    19	    public ReservationController(RoomService roomService, ReservationService reservationService,
    20	                               MessageService messageService, ReportService reportService) {
    21	        this.roomService = roomService;
    22	        this.reservationService = reservationService;
    23	        this.messageService = messageService;
    24	        this.reportService = reportService;
    25	    }
    26	
    27	    public void registerRoutes(Javalin app) {
    28	        app.get("/rooms", this::listRooms);
    29	        app.post("/reservations", this::createReservation);
    30	        app.get("/reservations/{id}", this::getReservation);
    31	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
    32	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
    33	        app.post("/reservations/{id}/check-in", this::checkIn);
    34	        app.post("/reservations/{id}/check-out", this::checkOut);
    35	        app.get("/reservations/{id}/document", this::getDocument);
    36	        app.get("/messages", this::listMessages);
    37	        app.get("/reports/occupancy", this::occupancyReport);
    38	        app.get("/reports/revenue", this::revenueReport);
    39	        app.get("/reports/tourism-tax", this::tourismTaxReport);
    40	        app.get("/reports/rate-plans", this::ratePlansReport);
    41	        app.exception(ApiException.class, this::handleApiException);
    42	        app.exception(Exception.class, this::handleException);
    43	    }
    44	
    45	    private void listRooms(io.javalin.http.Context ctx) {
    46	        var rooms = roomService.getAllRooms();
    47	        var dtos = rooms.stream()
    48	            .map(RoomDTO::fromRoom)
    49	            .toList();
    50	        ctx.json(dtos);
    51	    }
    52	
    53	    private void createReservation(io.javalin.http.Context ctx) {
    54	        try {
    55	            CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
    56	
    57	            LocalDate checkIn = parseDate(req.checkIn);
    58	            LocalDate checkOut = parseDate(req.checkOut);
    59	
    60	            Reservation res = reservationService.createReservation(
    61	                req.roomNumber,
    62	                req.guestName,
    63	                req.guestEmail,
    64	                req.guestCpf,
    65	                checkIn,
    66	                checkOut,
    67	                req.guests,
    68	                RatePlan.valueOf(req.ratePlan)
    69	            );
    70	
    71	            ctx.status(201);
    72	            ctx.json(ReservationDTO.fromReservation(res));
    73	        } catch (DateTimeParseException | IllegalArgumentException e) {
    74	            ctx.status(400);
    75	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format or rate plan"));
    76	        }
    77	    }
    78	
    79	    private void getReservation(io.javalin.http.Context ctx) {
    80	        long id = Long.parseLong(ctx.pathParam("id"));
    81	        Reservation res = reservationService.getReservation(id);
    82	        ctx.json(ReservationDTO.fromReservation(res));
    83	    }
    84	
    85	    private void confirmReservation(io.javalin.http.Context ctx) {
    86	        long id = Long.parseLong(ctx.pathParam("id"));
    87	        ConfirmationRequest req = ctx.bodyAsClass(ConfirmationRequest.class);
    88	
    89	        Reservation res = reservationService.confirmReservation(id, parseMoney(req.amountPaid));
    90	        ctx.json(ReservationDTO.fromReservation(res));
    91	    }
    92	
    93	    private void cancelReservation(io.javalin.http.Context ctx) {
    94	        long id = Long.parseLong(ctx.pathParam("id"));
    95	        Reservation res = reservationService.cancelReservation(id);
    96	        ctx.json(ReservationDTO.fromReservation(res));
    97	    }
    98	
    99	    private void checkIn(io.javalin.http.Context ctx) {
   100	        long id = Long.parseLong(ctx.pathParam("id"));
   101	        Reservation res = reservationService.checkIn(id);
   102	        ctx.json(ReservationDTO.fromReservation(res));
   103	    }
   104	
   105	    private void checkOut(io.javalin.http.Context ctx) {
   106	        long id = Long.parseLong(ctx.pathParam("id"));
   107	        Receipt receipt = reservationService.checkOut(id);
   108	        ctx.json(ReceiptDTO.fromReceipt(receipt));
   109	    }
   110	
   111	    private void getDocument(io.javalin.http.Context ctx) {
   112	        long id = Long.parseLong(ctx.pathParam("id"));
   113	        Receipt receipt = reservationService.getDocument(id);
   114	        ctx.json(ReceiptDTO.fromReceipt(receipt));
   115	    }
   116	
   117	    private void listMessages(io.javalin.http.Context ctx) {
   118	        var messages = messageService.getMessages();
   119	        var dtos = messages.stream()
   120	            .map(MessageDTO::fromMessage)
   121	            .toList();
   122	        ctx.json(dtos);
   123	    }
   124	
   125	    private void occupancyReport(io.javalin.http.Context ctx) {
   126	        String dateStr = ctx.queryParam("date");
   127	        if (dateStr == null) {
   128	            ctx.status(400);
   129	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Date parameter required"));
   130	            return;
   131	        }
   132	
   133	        try {
   134	            LocalDate date = parseDate(dateStr);
   135	            String report = reportService.generateOccupancyReport(date);
   136	            ctx.header("Content-Type", "text/csv; charset=utf-8");
   137	            ctx.result(report);
   138	        } catch (DateTimeParseException e) {
   139	            ctx.status(400);
   140	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
   141	        }
   142	    }
   143	
   144	    private void revenueReport(io.javalin.http.Context ctx) {
   145	        String monthStr = ctx.queryParam("month");
   146	        if (monthStr == null) {
   147	            ctx.status(400);
   148	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Month parameter required"));
   149	            return;
   150	        }
   151	
   152	        try {
   153	            YearMonth month = YearMonth.parse(monthStr);
   154	            String report = reportService.generateRevenueReport(month);
   155	            ctx.header("Content-Type", "text/csv; charset=utf-8");
   156	            ctx.result(report);
   157	        } catch (DateTimeParseException e) {
   158	            ctx.status(400);
   159	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
   160	        }
   161	    }
   162	
   163	    private void tourismTaxReport(io.javalin.http.Context ctx) {
   164	        String monthStr = ctx.queryParam("month");
   165	        if (monthStr == null) {
   166	            ctx.status(400);
   167	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Month parameter required"));
   168	            return;
   169	        }
   170	
   171	        try {
   172	            YearMonth month = YearMonth.parse(monthStr);
   173	            String report = reportService.generateTourismTaxReport(month);
   174	            ctx.header("Content-Type", "text/csv; charset=utf-8");
   175	            ctx.result(report);
   176	        } catch (DateTimeParseException e) {
   177	            ctx.status(400);
   178	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
   179	        }
   180	    }
   181	
   182	    private void ratePlansReport(io.javalin.http.Context ctx) {
   183	        String monthStr = ctx.queryParam("month");
   184	        if (monthStr == null) {
   185	            ctx.status(400);
   186	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Month parameter required"));
   187	            return;
   188	        }
   189	
   190	        try {
   191	            YearMonth month = YearMonth.parse(monthStr);
   192	            String report = reportService.generateRatePlansReport(month);
   193	            ctx.header("Content-Type", "text/csv; charset=utf-8");
   194	            ctx.result(report);
   195	        } catch (DateTimeParseException e) {
   196	            ctx.status(400);
   197	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
   198	        }
   199	    }
   200	
   201	    private void handleApiException(ApiException e, io.javalin.http.Context ctx) {
   202	        ctx.status(e.getStatusCode());
   203	        ctx.json(new ErrorResponse(e.getCode(), e.getMessage()));
   204	    }
   205	
   206	    private void handleException(Exception e, io.javalin.http.Context ctx) {
   207	        ctx.status(500);
   208	        ctx.json(new ErrorResponse("INTERNAL_ERROR", "Internal server error"));
   209	    }
   210	
   211	    private LocalDate parseDate(String dateStr) {
   212	        return LocalDate.parse(dateStr);
